char	**input_array;
//****************
int	row_len = 0;
int	row_count = 0;
//******************
int	i;
int	j;
//******************
int	xmas = 0;
//******************
char	**ft_split(char const *s, char c);
//******************
void	check_N()
{
	if ((i-1) >= 0 && input_array[i-1][j] == 'M')
	{
		if ((i-2) >= 0 && input_array[i-2][j] == 'A')
		{
			if ((i-3) >= 0 && input_array[i-3][j] == 'S')
				xmas++;
		}
	}
}
void	check_S()
{
	if ((i+2) <= row_count && input_array[i+1][j] == 'M')
	{
		if ((i+3) <= row_count && input_array[i+2][j] == 'A')
		{
			if ((i+4) <= row_count && input_array[i+3][j] == 'S')
				xmas++;
		}
	}
}
void	check_W()
{
	if ((j-1) >= 0 && input_array[i][j-1] == 'M')
	{
		if ((j-2) >= 0 && input_array[i][j-2] == 'A')
		{
			if ((j-3) >= 0 && input_array[i][j-3] == 'S')
				xmas++;
		}
	}
}
void	check_E()
{
	if ((j+2) <= row_len && input_array[i][j+1] == 'M')
	{
		if ((j+3) <= row_len && input_array[i][j+2] == 'A')
		{
			if ((j+4) <= row_len && input_array[i][j+3] == 'S')
				xmas++;
		}
	}
}
void	check_NW()
{
	if ((j-1) >= 0 && (i-1) >= 0 && input_array[i-1][j-1] == 'M')
	{
		if ((j-2) >= 0 && (i-2) >= 0 && input_array[i-2][j-2] == 'A')
		{
			if ((j-3) >= 0 && (i-3) >= 0 && input_array[i-3][j-3] == 'S')
				xmas++;
		}
	}
}
void	check_NE()
{
	if ((j+2) <= row_len && (i-1) >= 0 && input_array[i-1][j+1] == 'M')
	{
		if ((j+3) <= row_len && (i-2) >= 0 && input_array[i-2][j+2] == 'A')
		{
			if ((j+4) <= row_len && (i-3) >= 0 && input_array[i-3][j+3] == 'S')
				xmas++;
		}
	}
}
void	check_SW()
{
	if ((j-1) >= 0 && (i+2) <= row_count && input_array[i+1][j-1] == 'M')
	{
		if ((j-2) >= 0 && (i+3) <= row_count && input_array[i+2][j-2] == 'A')
		{
			if ((j-3) >= 0 && (i+4) <= row_count && input_array[i+3][j-3] == 'S')
				xmas++;
		}
	}
}
void	check_SE()
{
	if ((j+2) <= row_len && (i+2) <= row_count && input_array[i+1][j+1] == 'M')
	{
		if ((j+3) <= row_len && (i+3) <= row_count && input_array[i+2][j+2] == 'A')
		{
			if ((j+4) <= row_len && (i+4) <= row_count && input_array[i+3][j+3] == 'S')
				xmas++;
		}
	}
}






int	main()
{	
	i = 0;
	while (input[i] != ':')
	{
		row_len++;
		i++;
	}
	
	//********************
	printf("row_len: %d\n", row_len);
	//********************
	
	
	i = 0;
	while (input[i] != '\0')
	{
		if (input[i+1] == ':' || input[i+1] == '\0')
		{
			row_count++;
		}
		i++;
	}
	
	//*******************
	printf("row_count: %d\n", row_count);
	
	input_array = ft_split(input, ':');
	
	i = 0;
	j = 0;
	
	while (i < row_count)
	{
		j = 0;
		while (j < row_len)
		{
			//encontramos uuna coinidencia
			if (input_array[i][j] == 'X')
			{
				//checkaemos las 8 direciones en orden N,NE,E,SE,S,SW,W,NW
				check_N();
				check_NE();
				check_E();
				check_SE();
				check_S();
				check_SW();
				check_W();
				check_NW();
			}
			
			
			
			
			
			j++;
		}
		
		
		
		
		
		
		
		
		
		
		
		i++;
	}
	
	printf("%d", xmas);
}
